import{_ as s,o as a,c as t,a3 as i}from"./chunks/framework.Ch_0qWu9.js";const u=JSON.parse('{"title":"Source packages","description":"","frontmatter":{"sourcePath":"docs/source-delivery.md","sourceUrl":"https://github.com/MoonshotAI/TCSExam/blob/2195a1c2af3b46d864ca365f3ec640ee39fd3da2/docs/source-delivery.md","alternateUrl":"/TCSExam/docs/zh/source-delivery/","alternateAnchors":{"source-packages":"source-packages","build-from-source":"build-from-source","export-and-redistribution":"export-and-redistribution"}},"headers":[],"relativePath":"source-delivery/index.md","filePath":"source-delivery/index.md"}'),r={name:"source-delivery/index.md"};function n(o,e,d,c,l,p){return a(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="source-packages" tabindex="-1">Source packages <a class="header-anchor" href="#source-packages" aria-label="Permalink to &quot;Source packages&quot;">​</a></h1><p>This reference describes the TCSExam source package and its build entry points. It is for users preparing environments from source or creating a source distribution.</p><p>The repository contains 100 tasks in 130 task folders: 70 shared Lean folders and 30 Solver tasks with separate Online and Offline folders. Lite selects 20 tasks from across Full&#39;s task categories, using these same folders.</p><p>Read the table by directory. Runtime outputs are kept separately from source.</p><table tabindex="0"><thead><tr><th>Path</th><th>Contents</th></tr></thead><tbody><tr><td><code>tasks/</code></td><td>Instructions, task configuration, environment recipes and verifiers</td></tr><tr><td><code>suites/</code></td><td>Full/Lite selections and task/protocol paths</td></tr><tr><td><code>src/tcsexam/</code></td><td>CLI, score calculation, judging backend and fixed scoring references</td></tr><tr><td><code>assets/</code></td><td>Resource inventories, pinned input recipes, environment builds and notices</td></tr><tr><td><code>docs/</code></td><td>Usage, technical references, sources and licenses</td></tr></tbody></table><p>Each task uses Harbor&#39;s folder format with <code>instruction.md</code>, <code>task.toml</code>, <code>environment/</code> and <code>tests/</code>. Runtime images, bulk prepared datasets, model outputs and reference-answer archives are separate products.</p><h2 id="build-from-source" tabindex="-1">Build from source <a class="header-anchor" href="#build-from-source" aria-label="Permalink to &quot;Build from source&quot;">​</a></h2><p>Follow <a href="/TCSExam/docs/getting-started/">getting started</a> to install the CLI and check the host. The build entry points are:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tcsexam</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> source-inputs</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tcsexam</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --suite</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lite</span></span></code></pre></div><p><code>source-inputs</code> prepares fixed public Lean source archives. <code>build</code> prepares the selected dependencies and images on the Docker host. Use <a href="/TCSExam/docs/resources/">resource preparation</a> for fixed inputs, acquisition failures, image manifests and selecting a smaller build. Ordinary evaluation uses the task inputs and verifiers; reference-answer archives are optional inputs for the <a href="/TCSExam/docs/oracle-answers/">reference-answer tooling</a>.</p><p>To prepare all task variants, build Full once with Online Solver and then the Offline Solver track:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tcsexam</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --suite</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> full</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --solver-protocol</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> online</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tcsexam</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --suite</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> full</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --track</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> solver</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --solver-protocol</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> offline</span></span></code></pre></div><p>Configure the model and check the chosen runtime selection through <a href="/TCSExam/docs/running/">running evaluations</a>. Online Solver additionally needs its <a href="/TCSExam/docs/backend/docker/">backend service</a>.</p><h2 id="export-and-redistribution" tabindex="-1">Export and redistribution <a class="header-anchor" href="#export-and-redistribution" aria-label="Permalink to &quot;Export and redistribution&quot;">​</a></h2><p><a href="/TCSExam/docs/contributing/">CONTRIBUTING.md</a> contains source-export commands and development checks. Export keeps source separate from caches, credentials and evaluation outputs. Keep runtime images and job directories separately when preserving an experiment.</p><p>Preserve the applicable <a href="/TCSExam/docs/licenses/">licenses and notices</a>. <a href="/TCSExam/docs/licenses/distribution/">Distribution conditions</a> describe which third-party materials and images can be shared.</p>`,16)])])}const k=s(r,[["render",n]]);export{u as __pageData,k as default};
